    17→// blockRangeBatcher encapsulates the logic for splitting up a block range request into fixed-size batches of
    18→// blocks that are retrieved from the database, ensured to be canonical, sequential and unique.
    19→// If a non-nil value for ticker is set, it will be used to pause between batches lookups, as a rate-limiter.
    20→type blockRangeBatcher struct {
    21→	start   primitives.Slot
    22→	end     primitives.Slot
    23→	size    uint64
    24→	db      db.NoHeadAccessDatabase
    25→	limiter *limiter
    26→	ticker  *time.Ticker
