    32→func newBlockRangeBatcher(rp rangeParams, bdb db.NoHeadAccessDatabase, limiter *limiter, canonical canonicalChecker, ticker *time.Ticker) (*blockRangeBatcher, error) {
    33→	if bdb == nil {
    34→		return nil, errors.New("nil db param, unable to initialize blockRangeBatcher")
    35→	}
    36→	if limiter == nil {
    37→		return nil, errors.New("nil limiter param, unable to initialize blockRangeBatcher")
    38→	}
    39→	if canonical == nil {
    40→		return nil, errors.New("nil canonicalChecker param, unable to initialize blockRangeBatcher")
    41→	}
    42→	if ticker == nil {
    43→		return nil, errors.New("nil ticker param, unable to initialize blockRangeBatcher")
    44→	}
    45→	if rp.size == 0 {
    46→		return nil, fmt.Errorf("invalid batch size of %d", rp.size)
    47→	}
    48→	if rp.end < rp.start {
    49→		return nil, fmt.Errorf("batch end slot %d is lower than batch start %d", rp.end, rp.start)
    50→	}
    51→	cf := &canonicalFilter{canonical: canonical}
    52→	return &blockRangeBatcher{
    53→		start:   rp.start,
    54→		end:     rp.end,
    55→		size:    rp.size,
    56→		db:      bdb,
    57→		limiter: limiter,
    58→		ticker:  ticker,
    59→		cf:      cf,
    60→	}, nil
    61→}
